<script>
import { updateMeta } from "@/utils/meta";
import { formatMonthJa } from "@/utils/date";
import { SITE_URL } from "@/constants/routeMeta";
import { snsLinks } from "@/constants/snsLinks";
import exshipsLogo from "@/assets/exshipsLogo.webp";

// コピー結果のツールチップを表示しておく時間
const COPY_FEEDBACK_MS = 1500;

export default {
  name: "BlogDetailView",
  data: () => ({
    exshipsLogo,
    pageVisible: false,
    loading: true,
    post: null,
    // null | "network" | "notfound"
    loadError: null,
    // "idle" | "copied" | "failed"
    copyState: "idle",
    copyTimer: 0,
  }),
  computed: {
    // X のロゴ・ブランド色は Contact の SNS 導線と同じ定義を使う
    xLink() {
      return snsLinks.find((l) => l.id === "x");
    },
    shareUrl() {
      return SITE_URL + this.$route.path;
    },
    xShareUrl() {
      const text = this.post ? this.post.title : "";
      return (
        "https://x.com/intent/post?text=" +
        encodeURIComponent(text) +
        "&url=" +
        encodeURIComponent(this.shareUrl)
      );
    },
    copyMessage() {
      if (this.copyState === "copied") return "コピーしました";
      if (this.copyState === "failed") return "コピーできませんでした";
      return "";
    },
  },
  watch: {
    // 記事から別の記事へ遷移してもコンポーネントは再利用されるため、idを監視する
    "$route.params.id"(id) {
      if (id && this.$route.name === "blog-detail") {
        this.loadPost();
      }
    },
  },
  mounted() {
    this.loadPost();
    setTimeout(() => (this.pageVisible = true), 100);
  },
  beforeUnmount() {
    clearTimeout(this.copyTimer);
  },
  methods: {
    formatMonthJa,
    async copyLink() {
      const url = this.shareUrl;
      let ok = false;
      try {
        if (navigator.clipboard && window.isSecureContext) {
          await navigator.clipboard.writeText(url);
          ok = true;
        } else {
          // 非 secure context（LAN の http 等）向けフォールバック
          const ta = document.createElement("textarea");
          ta.value = url;
          ta.setAttribute("readonly", "");
          ta.style.position = "fixed";
          ta.style.opacity = "0";
          document.body.appendChild(ta);
          ta.select();
          ok = document.execCommand("copy");
          document.body.removeChild(ta);
        }
      } catch (e) {
        ok = false;
      }
      this.copyState = ok ? "copied" : "failed";
      clearTimeout(this.copyTimer);
      this.copyTimer = setTimeout(() => {
        this.copyState = "idle";
      }, COPY_FEEDBACK_MS);
    },
    // 本文は記事ごとの遅延チャンク（一覧ページには本文が含まれない）
    async loadPost() {
      const id = this.$route.params.id;
      this.loading = true;
      this.loadError = null;
      try {
        const { default: post } = await import(
          /* webpackChunkName: "blog-post-[request]" */
          `@/content/blog/${id}.md`
        );
        this.post = post;
        // router.afterEach が設定する汎用メタを記事別の値で上書きする
        // （descriptionの整形は scripts/generate-seo-pages.js の静的生成と揃える）
        updateMeta({
          title: post.title,
          description: (post.excerpt || post.title).slice(0, 120),
          path: this.$route.path,
          type: "article",
        });
      } catch (e) {
        this.post = null;
        // webpack のチャンク取得失敗（オフライン等）は ChunkLoadError、
        // 存在しない id は "Cannot find module" で reject される
        const isNetwork =
          e && (e.name === "ChunkLoadError" || /Loading chunk/i.test(e.message || ""));
        this.loadError = isNetwork ? "network" : "notfound";
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

